-- 000045_seed_moves_manon.down.sql
-- M14-03d: manon の moves + official_ja_move alias + recovery を手入力 CSV 由来で投入する(第二波)。
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- 移動 system move は CSV に無い(seed の投入元は 000004_data_seed_moves)。
-- FK 依存順 characters→moves→preset_aliases。

-- ===== manon =====
DELETE FROM preset_aliases WHERE move_id IN (
    SELECT m.id FROM moves m JOIN characters c ON c.id = m.character_id WHERE c.code = 'manon' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code IN ('standing_light_punch', 'standing_light_kick', 'standing_medium_punch', 'standing_medium_kick', 'standing_heavy_punch', 'standing_heavy_kick', 'crouching_light_punch', 'crouching_light_kick', 'crouching_medium_punch', 'crouching_medium_kick', 'crouching_heavy_punch', 'crouching_heavy_kick', 'jumping_light_punch', 'jumping_light_kick', 'jumping_medium_punch', 'jumping_medium_kick', 'jumping_heavy_punch', 'jumping_heavy_kick', 'drive_impact', 'throw_forward', 'throw_back', 'drive_parry', 'reverence', 'tomoe_derriere', 'a_terre', 'en_haut', 'en_haut_1hit', 'allonge', 'temps_lie', 'manege_dore_light', 'manege_dore_medium', 'manege_dore_heavy', 'manege_dore_od', 'rond_point_light', 'rond_point_medium', 'rond_point_heavy', 'rond_point_od', 'degage_light', 'degage_medium', 'degage_heavy', 'degage_od', 'renverse_light', 'renverse_medium', 'renverse_heavy', 'renverse_od', 'renverse_feint_light', 'renverse_feint_medium', 'renverse_feint_heavy', 'renverse_feint_od', 'grand_fouette_light', 'grand_fouette_medium', 'grand_fouette_heavy', 'grand_fouette_od', 'sa1_arabesque', 'sa2_etoile', 'sa3_pas_de_deux', 'ca_pas_de_deux', 'rush_standing_light_punch', 'rush_standing_light_kick', 'rush_standing_medium_punch', 'rush_standing_medium_kick', 'rush_standing_heavy_punch', 'rush_standing_heavy_kick', 'rush_crouching_light_punch', 'rush_crouching_light_kick', 'rush_crouching_medium_punch', 'rush_crouching_medium_kick', 'rush_crouching_heavy_punch', 'rush_crouching_heavy_kick', 'rush_reverence', 'rush_tomoe_derriere', 'rush_en_haut_1hit'));
DELETE FROM moves WHERE character_id IN (SELECT c.id FROM characters c WHERE c.code = 'manon' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6'))
